{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this analysis — are we maximizing the total value of exports (i.e., the value of domestically produced goods sold on the world market), or something else such as minimizing the value of imports or maximizing net trade balance?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options within one sentence."
}

